def checkWays(pairs):
    from collections import defaultdict
    adj = defaultdict(set)
    for a, b in pairs:
        adj[a].add(b)
        adj[b].add(a)
    nodes = list(adj.keys())
    n = len(nodes)
    nodes.sort(key=lambda x: len(adj[x]), reverse=True)
    ans = 1
    for u in nodes:
        du = len(adj[u])
        parent = None
        pdeg = None
        for v in nodes:
            if v == u:
                continue
            if v in adj[u] and len(adj[v]) >= du:
                if parent is None or len(adj[v]) < pdeg:
                    parent = v
                    pdeg = len(adj[v])
        if parent is None:
            if du != n - 1:
                return 0
        else:
            if pdeg == du:
                ans = 2
            for w in adj[u]:
                if w != parent and w not in adj[parent]:
                    return 0
    return ans
